+  bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(dist(b,player)<1.5&&player.invuln<=0){player.hp-=b.kind==='heli'?12:8;player.invuln=.45;player.stun=.16;spawnParticles(player.x,player.y,'#ffb14a',5);b.life=0;showToast('Tertembak! Cari perlindungan.')}});bullets=bullets.filter(b=>b.life>0);particleList.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particleList=particleList.filter(p=>p.life>0);
