+}
+function winGame(){mode='win';ui.overlay.style.display='grid';ui.overlay.innerHTML='<section class="card"><div class="eyebrow">SINYAL KOTA TELAH DIKUASAI</div><h1>KOTA<br><em>TERTIDUR.</em></h1><p>Menara transmisi telah menyebarkan gelombang simbiot ke seluruh kota. Kamu berhasil menyelinap melewati patroli dan menuntaskan misi.</p><button class="primary" id="again">MAIN LAGI</button><p class="note">Terima kasih telah bermain VENOM: Kota dalam Bayangan</p></section>';document.getElementById('again').onclick=startGame}
+function endGame(won){mode=won?'win':'lost';ui.overlay.style.display='grid';ui.overlay.innerHTML=`<section class="card"><div class="eyebrow">${won?'MISI SELESAI':'SINYAL TERPUTUS'}</div><h1>${won?'KOTA':'KAMU'}<br><em>${won?'TERTIDUR.':'TERDETEKSI.'}</em></h1><p>${won?'Menara transmisi dikuasai.':'Penjaga berhasil menghentikan infiltrasi. Atur rute, manfaatkan sprint, dan hindari sorot helikopter.'}</p><button class="primary" id="again">${won?'MAIN LAGI':'COBA LAGI'}</button></section>`;document.getElementById('again').onclick=startGame}

